algorithms.pseudocode:
def call(dep, method, req, ctx):
    p = policies.get(dep, method)
    budget.onRequest()                      # deposit 0.1 token
    for attempt in range(1, p.max_attempts + 1):
        if ctx.remaining() < p.min_useful_ms:
            return fallback_or(DeadlineExceeded)
        if not breaker[dep].allow():
            return fallback_or(CircuitOpen)
        permit = bulkhead[dep].tryAcquire()
        if permit is None:
            return fallback_or(BulkheadFull)
        t = min(p.per_try_timeout, ctx.remaining() - MARGIN)
        try:
            res = transport.send(req, timeout=t, deadline=ctx.toHeader())
            breaker[dep].onSuccess(res.latency)
            return res
        except Exception as e:
            kind = classify(e)
            breaker[dep].onFailure(kind)
            if kind == NON_RETRYABLE or not req.idempotent_or_keyed:
                return fallback_or(e)
            if attempt == p.max_attempts or not budget.tryAcquireRetry():
                return fallback_or(e)
            sleep(backoff.next(attempt, e.retry_after))
        finally:
            bulkhead[dep].release(permit)

def next(attempt, retry_after=None):
    if retry_after:                       # server push-back wins
        return retry_after + random(0, 0.1 * retry_after)
    ceiling = min(CAP_MS, BASE_MS * 2 ** (attempt - 1))
    return random_uniform(0, ceiling)     # full jitter

def onResult(ok, latency):
    b = ring[now_sec % 10]; b.reset_if_stale(now_sec)
    b.calls += 1; b.fail += (not ok); b.slow += latency > SLOW_MS
    if state == CLOSED:
        calls, fail, slow = sum_ring()
        if calls >= MIN_CALLS and (fail/calls >= 0.5 or slow/calls >= 0.8):
            state = OPEN; opened_at = now()
    elif state == HALF_OPEN:
        probes_done += 1; probes_ok += ok
        if probes_done == PROBES:
            state = CLOSED if probes_ok >= 4 else OPEN; opened_at = now()

def allow():
    if state == OPEN and now() - opened_at >= OPEN_S:
        state = HALF_OPEN; probes_issued = probes_done = probes_ok = 0
    if state == HALF_OPEN:
        if probes_issued < PROBES: probes_issued += 1; return True
        return False
    return state == CLOSED

RATIO = 0.1; MAX_TOKENS = 100
def onRequest():  tokens = min(MAX_TOKENS, tokens + RATIO)
def tryAcquireRetry():
    if tokens >= 1: tokens -= 1; return True
    return False
